// Cross-language wire-format proof: this fixture was generated by the
// BACKEND (Python) -- packed, Ed25519-signed via PyNaCl, and
// XChaCha20-Poly1305 encrypted using `app/mesh/wire_format.py` and
// `app/security/mesh_crypto.py` -- and is decoded here using only the real
// Dart client modules.
//
// This is not a Dart reimplementation testing itself: it is proof that two
// independent implementations, in two different languages, agree byte for
// byte on the wire contract, in BOTH directions (see
// backend/tests/test_wire_format_interop.py for the other direction).
//
// Regenerate by running the Python snippet documented in that file.

import 'dart:convert';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:lifesearch_mobile/core/crypto/device_identity.dart';
import 'package:lifesearch_mobile/core/crypto/mesh_crypto.dart';
import 'package:lifesearch_mobile/core/crypto/sodium_provider.dart';
import 'package:lifesearch_mobile/core/crypto/wire_format.dart';
import 'package:sodium/sodium.dart';

const String _devicePublicKeyB64 = '5KDlujmTxQ787vKWqLIHpGEc3mscKF15FgH13kyOel4=';
const String _sectorKeyB64 = '2gwQg4skCK6jK3Xj1/FcFmcJW9obhUeliU0pV1kXlj0=';
const String _blobB64 =
    'xQIU8U0PhPLujlBDIO/7OtfowqDfzPdomGLvEQh+hpBYRxfjW4lHybrfBeCR1MKIfv5OeeYMB7ZlxC2oYN59E0A8JHVHgW413luSP1Se96h1mAw8xK3r0i/1BuzgjrSJhgMrBjfEdZLWlfTZmc/FTe5UhdwKuIpVb03edV0ezztaXiw=';

const int _expectedWireId = 99887766;
const int _expectedRecordedAtMs = 1780000012345;
const double _expectedLat = 32.109383;
const double _expectedLng = 34.855121;
const double _expectedAccuracyM = 12.4;
const double _expectedSpeedMps = 0.83;
const int _expectedBatteryPct = 41;
const bool _expectedIsMocked = true;

void main() {
  late Sodium sodium;
  late DeviceIdentity identity;
  late MeshCrypto crypto;

  setUpAll(() async {
    sodium = await SodiumProvider.instance();
    identity = DeviceIdentity(sodium);
    crypto = MeshCrypto(sodium);
  });

  test('decrypts, verifies, and unpacks a Python-generated packet', () {
    final sectorKey = sodium.secureCopy(base64Decode(_sectorKeyB64));
    final devicePublicKey = base64Decode(_devicePublicKeyB64);
    final blob = base64Decode(_blobB64);

    final bundle = crypto.decrypt(sectorKey, blob);
    final Uint8List packedPayload = bundle.sublist(0, payloadBytes);
    final Uint8List signature = bundle.sublist(payloadBytes);

    expect(signature.length, equals(ed25519SignatureBytes));
    expect(identity.verify(devicePublicKey, packedPayload, signature), isTrue);

    final payload = unpackPointPayload(packedPayload);
    expect(payload.wireId, equals(_expectedWireId));
    expect(payload.recordedAtMs, equals(_expectedRecordedAtMs));
    expect(payload.lat, closeTo(_expectedLat, 1e-6));
    expect(payload.lng, closeTo(_expectedLng, 1e-6));
    expect(payload.accuracyM, closeTo(_expectedAccuracyM, 0.05));
    expect(payload.speedMps, closeTo(_expectedSpeedMps, 0.005));
    expect(payload.batteryPct, equals(_expectedBatteryPct));
    expect(payload.isMocked, equals(_expectedIsMocked));

    sectorKey.dispose();
  });

  test('a forged signature over the Python-produced payload is rejected', () {
    final sectorKey = sodium.secureCopy(base64Decode(_sectorKeyB64));
    final devicePublicKey = base64Decode(_devicePublicKeyB64);
    final blob = base64Decode(_blobB64);

    final bundle = crypto.decrypt(sectorKey, blob);
    final Uint8List packedPayload = bundle.sublist(0, payloadBytes);
    final Uint8List signature = Uint8List.fromList(
      bundle.sublist(payloadBytes),
    );
    signature[signature.length - 1] ^= 0xFF;

    expect(
      identity.verify(devicePublicKey, packedPayload, signature),
      isFalse,
    );

    sectorKey.dispose();
  });

  test('the wrong sector key fails to decrypt the Python-produced blob', () {
    final wrongKey = sodium.secureRandom(meshKeyBytes);
    final blob = base64Decode(_blobB64);

    expect(
      () => crypto.decrypt(wrongKey, blob),
      throwsA(isA<MeshCryptoException>()),
    );

    wrongKey.dispose();
  });
}
